% Solver generated by SolverMapp
clear; clc;

%% Stage 0: Inputs and start values of state variables
y          = 1.0; % [State] (-) Marching state variable (y_0 = 1)
N          = 5; % [Input] (-) Number of force elements
f_i        = 10.0 * ones(1, N); % [Input] (N) Element force array
x_1        = 0.0; % [Input] (m) Lower integration bound
x_2        = 2.0; % [Input] (m) Upper integration bound
T          = 300.0; % [State] (K) Converged temperature state
p          = 5e6; % [Input] (Pa) Gas pressure
a          = 0.3640; % [Input] (Pa m^6/mol^2) Van der Waals attraction constant (CO2)
b          = 4.267e-5; % [Input] (m^3/mol) Van der Waals co-volume (CO2)
R_u        = 8.314; % [Input] (J/(mol·K)) Universal gas constant
T_g        = 280; % [Input] (K) Gas temperature

%% Stage 1
% [MARCHING] State step recurrence: y_{n+1} = y_n + 1
for step = 1:10
    y = y + 1;
end
% [SUMMATION] Total force summation: F_{total} = \sum_{i=1}^{N} f_i
F_total = 0;
for i = 1:N
    F_total = F_total + f_i(i);
end
% [IMPLICIT] Van der Waals equation of state: \left(p + \frac{a}{v^2}\right)\left(v - b\right) = R_u T_g
% Newton–Raphson on the residual (left side - right side) = 0, solved for v
% Branch: b <= v
res_v = @(v) (p + ((a) / (v^2))) * (v - b) - (R_u * T_g);
v = 4.66e-4; % initial guess
v = max(v, b); % start on the branch
converged = false;
for it = 1:50
    h_nr = 1e-6 * max(abs(v), 1e-6);
    dr_nr = (res_v(v + h_nr) - res_v(v - h_nr)) / (2 * h_nr);
    if dr_nr == 0, warning('Zero derivative in the Newton iteration for v'); break; end
    v_new = v - res_v(v) / dr_nr;
    if v_new < b, v_new = 0.5 * (v + b); end % stay on the branch
    if abs(v_new - v) < 1e-10 * (1 + abs(v)), v = v_new; converged = true; break; end
    v = v_new;
end
if ~converged, warning('v did not converge in %d iterations', 50); end

%% Stage 2
% [INTEGRAL] Boundary work integral: W = \int_{x_1}^{x_2} F_{total} \, dx
% Trapezoidal rule over x from x_1 to x_2
n_quad = 100;
dx = (x_2 - x_1) / n_quad;
W = 0;
for q = 0:n_quad
    x = x_1 + q * dx;
    w_q = 1 - 0.5 * (q == 0 || q == n_quad);
    W = W + w_q * (F_total) * dx;
end

%% Stage 3
% [CONVERGENCE] Non-linear relaxation update: T_{new} = 0.5 T_{old} + 0.02 W
converged = false;
for it = 1:500
    T_new = 0.5 * T + 0.02 * W;
    if abs(T_new - T) < 1e-6, T = T_new; converged = true; break; end
    T = T_new;
end
if ~converged, warning('T did not converge in %d iterations', 500); end

%% Results
fprintf('%-12s = %s\n', 'y', mat2str(y));
fprintf('%-12s = %s\n', 'N', mat2str(N));
fprintf('%-12s = %s\n', 'f_i', mat2str(f_i));
fprintf('%-12s = %s\n', 'F_total', mat2str(F_total));
fprintf('%-12s = %s\n', 'x_1', mat2str(x_1));
fprintf('%-12s = %s\n', 'x_2', mat2str(x_2));
fprintf('%-12s = %s\n', 'W', mat2str(W));
fprintf('%-12s = %s\n', 'T', mat2str(T));
fprintf('%-12s = %s\n', 'p', mat2str(p));
fprintf('%-12s = %s\n', 'a', mat2str(a));
fprintf('%-12s = %s\n', 'b', mat2str(b));
fprintf('%-12s = %s\n', 'R_u', mat2str(R_u));
fprintf('%-12s = %s\n', 'T_g', mat2str(T_g));
fprintf('%-12s = %s\n', 'v', mat2str(v));